import React, { useRef, useState, useEffect } from 'react';
import { motion } from 'motion/react';
import type { Project, Language } from '../types';

interface ProjectCardProps {
  project: Project;
  lang: Language;
  onSelect: (project: Project) => void;
  index?: number;
}

export const ProjectCard: React.FC<ProjectCardProps> = ({ project, lang, onSelect, index = 0 }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isVideoLoading, setIsVideoLoading] = useState(false);
  const [shouldLoadVideo, setShouldLoadVideo] = useState(false);

  // Progressive staggered loader: load light thumbnails first,
  // then sequentially warmup videos one by one after initial page load
  useEffect(() => {
    if (isPlaying) {
      setShouldLoadVideo(true);
      return;
    }

    const timer = setTimeout(() => {
      if (typeof window !== 'undefined' && 'requestIdleCallback' in window) {
        (window as any).requestIdleCallback(() => setShouldLoadVideo(true));
      } else {
        setShouldLoadVideo(true);
      }
    }, 1500 + Math.min(index * 600, 15000));

    return () => clearTimeout(timer);
  }, [index, isPlaying]);

  const handleMouseEnter = () => {
    setShouldLoadVideo(true);
    if (videoRef.current) {
      setIsVideoLoading(true);
      const playPromise = videoRef.current.play();
      if (playPromise !== undefined) {
        playPromise
          .then(() => {
            setIsPlaying(true);
            setIsVideoLoading(false);
          })
          .catch(() => {
            setIsVideoLoading(false);
          });
      }
    }
  };

  const handleMouseLeave = () => {
    if (videoRef.current) {
      videoRef.current.pause();
      videoRef.current.currentTime = 0;
      setIsPlaying(false);
      setIsVideoLoading(false);
    }
  };

  return (
    <motion.article 
      layout
      initial={{ opacity: 0, y: 25 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: '-50px' }}
      transition={{ duration: 0.45, delay: Math.min(0.2, (index % 4) * 0.06), ease: 'easeOut' }}
      className="cipher-project-card"
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onClick={() => onSelect(project)}
    >
      {/* Media Cinema Container */}
      <div className="project-media-frame">
        {/* Loading shimmer when buffering video */}
        {isVideoLoading && (
          <div className="card-mini-loader">
            <span className="mini-loader-dot"></span>
            <span className="mini-loader-text">STREAMING...</span>
          </div>
        )}

        <img 
          src={project.image} 
          alt={project.title} 
          className={`project-img-poster ${isPlaying ? 'fade-out' : ''}`}
          loading="lazy"
          onError={(e) => {
            (e.target as HTMLElement).style.display = 'none';
          }}
        />

        {project.video && (
          <video 
            ref={videoRef}
            src={shouldLoadVideo ? project.video : undefined}
            loop 
            muted 
            playsInline
            preload={shouldLoadVideo ? "metadata" : "none"}
            className="project-video-preview"
            onCanPlay={() => setIsVideoLoading(false)}
            onWaiting={() => setIsVideoLoading(true)}
            onPlaying={() => setIsVideoLoading(false)}
          >
            <track kind="captions" />
          </video>
        )}

        <div className="project-media-overlay">
          <div className="overlay-top">
            <span className="media-index">{project.number}</span>
            <span className="media-type-pill">{project.type}</span>
          </div>
          <div className="overlay-center">
            <motion.span 
              className="explore-badge"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              <span>{lang === 'en' ? 'OPEN ARCHIVE' : 'VER EXPEDIENTE'}</span>
              <svg width="12" height="12" viewBox="0 0 12 12" fill="none">
                <path d="M1 11L11 1M11 1H3M11 1V9" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
              </svg>
            </motion.span>
          </div>
        </div>
      </div>

      {/* Editorial Meta */}
      <div className="project-info-block">
        <div className="info-header-row">
          <h3 className="project-card-title">
            <span className="num-prefix">{project.number} /</span> {project.title}
          </h3>
          <span className="client-badge">[{project.client}]</span>
        </div>

        <p className="project-card-summary">
          {project.summary[lang]}
        </p>

        <div className="project-card-footer">
          <div className="stack-pill-row">
            {project.stack.slice(0, 3).map((tech, i) => (
              <span key={i} className="tech-pill">{tech}</span>
            ))}
            {project.stack.length > 3 && (
              <span className="tech-pill tech-pill-more">+{project.stack.length - 3}</span>
            )}
          </div>
          <span className="open-link-indicator">
            {lang === 'en' ? 'CASE STUDY →' : 'CASO DE ESTUDIO →'}
          </span>
        </div>
      </div>
    </motion.article>
  );
};
