import React, { useRef, useState, useEffect } from 'react';

interface LazyVideoProps {
  src: string;
  poster?: string;
  className?: string;
  aspectRatio?: string;
  autoPlay?: boolean;
  loop?: boolean;
  muted?: boolean;
  playsInline?: boolean;
  onLoaded?: () => void;
  alt?: string;
  priority?: boolean;
}

export const LazyVideo: React.FC<LazyVideoProps> = ({
  src,
  poster,
  className = '',
  aspectRatio,
  autoPlay = true,
  loop = true,
  muted = true,
  playsInline = true,
  onLoaded,
  alt = 'Video preview',
  priority = false,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isInView, setIsInView] = useState(false);
  const [isVideoReady, setIsVideoReady] = useState(false);
  const [hasError, setHasError] = useState(false);

  useEffect(() => {
    const el = containerRef.current;
    if (!el || typeof IntersectionObserver === 'undefined') {
      setIsInView(true);
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        const entry = entries[0];
        if (entry.isIntersecting) {
          setIsInView(true);
          // Play video when scrolling into view
          if (videoRef.current && videoRef.current.paused && isVideoReady) {
            videoRef.current.play().catch(() => {});
          }
        } else {
          // Pause video when out of viewport to preserve mobile battery & GPU
          if (videoRef.current && !videoRef.current.paused) {
            videoRef.current.pause();
          }
        }
      },
      {
        rootMargin: '150px 0px 150px 0px', // Prefetch 150px before entering viewport
        threshold: 0.05,
      }
    );

    observer.observe(el);

    return () => {
      observer.disconnect();
    };
  }, [isVideoReady]);

  const handleCanPlay = () => {
    setIsVideoReady(true);
    if (autoPlay && videoRef.current && isInView) {
      videoRef.current.play().catch(() => {});
    }
    onLoaded?.();
  };

  return (
    <div 
      ref={containerRef} 
      className={`lazy-video-container ${className}`}
      style={aspectRatio ? { aspectRatio } : undefined}
    >
      {/* Lightweight Poster Image (Always visible until video is buffered) */}
      {poster && (
        <img
          src={poster}
          alt={alt}
          loading={priority ? 'eager' : 'lazy'}
          decoding="async"
          // @ts-expect-error fetchpriority attribute
          fetchpriority={priority ? 'high' : 'auto'}
          className={`lazy-video-poster ${isVideoReady ? 'faded-out' : 'visible'}`}
        />
      )}

      {/* Video Buffer Spinner Indicator */}
      {isInView && !isVideoReady && !hasError && (
        <div className="card-buffer-loader">
          <div className="buffer-spinner"></div>
        </div>
      )}

      {/* Video Tag: Only injected into DOM / assigned src once in viewport */}
      {isInView && (
        <video
          ref={videoRef}
          src={src}
          autoPlay={autoPlay}
          loop={loop}
          muted={muted}
          playsInline={playsInline}
          preload="metadata"
          className={`lazy-video-element ${isVideoReady ? 'loaded' : 'loading'}`}
          onLoadedData={handleCanPlay}
          onCanPlay={handleCanPlay}
          onError={() => setHasError(true)}
        >
          <track kind="captions" />
        </video>
      )}
    </div>
  );
};
