import { useState, lazy, Suspense } from 'react';
import type { Language, Project } from './types';
import { Header } from './components/Header';
import { CipherConstellation } from './components/CipherConstellation';
import { WorksSection } from './components/WorksSection';
import { Capabilities } from './components/Capabilities';
import { SpatialShowcase3D } from './components/SpatialShowcase3D';
import { About } from './components/About';
import { Footer } from './components/Footer';
import { PROJECTS } from './data/projects';

// Code-splitting: Only load heavy interactive modals on-demand
const ProjectModal = lazy(() => import('./components/ProjectModal').then(m => ({ default: m.ProjectModal })));
const ContactModal = lazy(() => import('./components/ContactModal').then(m => ({ default: m.ContactModal })));

export function App() {
  const [lang, setLang] = useState<Language>('en');
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [isContactOpen, setIsContactOpen] = useState<boolean>(false);

  return (
    <div className="cipher-app-root">
      {/* Fixed Luxury Minimalist Header */}
      <Header 
        lang={lang} 
        onLanguageChange={(newLang) => setLang(newLang)}
        onOpenContact={() => setIsContactOpen(true)}
      />

      <main>
        {/* 
          100vh FULLSCREEN CIPHER CONSTELLATION
          First thing seen upon entering: rotating 3D circular video orbit around the AF logo 
        */}
        <CipherConstellation 
          projects={PROJECTS} 
          lang={lang} 
          onSelectProject={(project) => setSelectedProject(project)} 
        />

        {/* 26 Projects Catalog with STAR methodology */}
        <WorksSection 
          projects={PROJECTS} 
          lang={lang} 
          onSelectProject={(project) => setSelectedProject(project)} 
        />

        {/* 4 Architectural Pillars & Engineering Mastery */}
        <Capabilities lang={lang} />

        {/* Dedicated 3D Spatial & Architectural CGI Showcase (M.S. UPF Barcelona) */}
        <SpatialShowcase3D 
          projects={PROJECTS} 
          lang={lang} 
          onSelectProject={(project) => setSelectedProject(project)} 
        />

        {/* Senior Craftsman Bio & Enterprise Credentials (Walmart, Norfolk Southern, Tec, UPF) */}
        <About lang={lang} />
      </main>

      {/* Direct Booking & Engagement Footer */}
      <Footer 
        lang={lang} 
        onOpenContact={() => setIsContactOpen(true)}
      />

      {/* Heavy Modals (Only downloaded on-demand when activated) */}
      <Suspense fallback={null}>
        {selectedProject && (
          <ProjectModal 
            project={selectedProject} 
            lang={lang} 
            onClose={() => setSelectedProject(null)}
            onOpenContact={() => setIsContactOpen(true)}
          />
        )}

        {isContactOpen && (
          <ContactModal 
            isOpen={isContactOpen}
            lang={lang}
            onClose={() => setIsContactOpen(false)}
          />
        )}
      </Suspense>
    </div>
  );
}

export default App;
