import React, { useState } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import type { Project, Language, ProjectCategory } from '../types';
import { ProjectCard } from './ProjectCard';
import { translations } from '../data/translations';

interface WorksSectionProps {
  projects: Project[];
  lang: Language;
  onSelectProject: (project: Project) => void;
}

export const WorksSection: React.FC<WorksSectionProps> = ({ projects, lang, onSelectProject }) => {
  const [activeFilter, setActiveFilter] = useState<ProjectCategory>('All');
  const t = translations[lang].works;

  const categories: ProjectCategory[] = [
    'All',
    'Featured',
    'Enterprise',
    'Creative Tech',
    'Healthcare',
    'Fintech & Insurance',
    'E-commerce',
  ];

  const filteredProjects = projects.filter((proj) => {
    if (activeFilter === 'All') return true;
    if (activeFilter === 'Featured') return proj.featured;
    if (activeFilter === 'Creative Tech') {
      return proj.category === 'Creative Tech' || proj.type === '3D' || proj.type === 'CGI';
    }
    return proj.category === activeFilter;
  });

  return (
    <section id="works" className="cipher-works-section">
      <div className="works-container">
        {/* Section Header with Motion Reveal */}
        <motion.div 
          className="section-header-block"
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
        >
          <div className="section-pre-title">{t.sectionLabel}</div>
          <div className="section-main-heading-row">
            <h2 className="section-title">{t.heading}</h2>
            <motion.span 
              key={filteredProjects.length}
              initial={{ scale: 1.2, color: '#ffffff' }}
              animate={{ scale: 1, color: '#888888' }}
              className="total-projects-counter"
            >
              [{filteredProjects.length} / {projects.length}]
            </motion.span>
          </div>
          <p className="section-subtext">{t.subheading}</p>
        </motion.div>

        {/* Filter Navigation */}
        <div className="cipher-filters-bar">
          <div className="filters-scroll-track">
            {categories.map((cat) => (
              <button
                key={cat}
                type="button"
                className={`filter-tab-btn ${activeFilter === cat ? 'active' : ''}`}
                onClick={() => setActiveFilter(cat)}
              >
                {t.filters[cat]}
              </button>
            ))}
          </div>
        </div>

        {/* Works Grid with Motion PopLayout Re-ordering */}
        <motion.div 
          className="cipher-projects-grid"
          layout
        >
          <AnimatePresence mode="popLayout">
            {filteredProjects.map((project, idx) => (
              <ProjectCard 
                key={project.id}
                project={project}
                lang={lang}
                onSelect={onSelectProject}
                index={idx}
              />
            ))}
          </AnimatePresence>
        </motion.div>
      </div>
    </section>
  );
};
